#[doc = "@brief Configures the Radio Notification signal.\n\n @note\n      - The notification signal latency depends on the interrupt priority settings of SWI used\n        for notification signal.\n      - To ensure that the radio notification signal behaves in a consistent way, the radio\n        notifications must be configured when there is no protocol stack or other SoftDevice\n        activity in progress. It is recommended that the radio notification signal is\n        configured directly after the SoftDevice has been enabled.\n      - In the period between the ACTIVE signal and the start of the Radio Event, the SoftDevice\n        will interrupt the application to do Radio Event preparation.\n      - Using the Radio Notification feature may limit the bandwidth, as the SoftDevice may have\n        to shorten the connection events to have time for the Radio Notification signals.\n\n @param[in]  type      Type of notification signal, see @ref NRF_RADIO_NOTIFICATION_TYPES.\n                       @ref NRF_RADIO_NOTIFICATION_TYPE_NONE shall be used to turn off radio\n                       notification. Using @ref NRF_RADIO_NOTIFICATION_DISTANCE_NONE is\n                       recommended (but not required) to be used with\n                       @ref NRF_RADIO_NOTIFICATION_TYPE_NONE.\n\n @param[in]  distance  Distance between the notification signal and start of radio activity, see @ref NRF_RADIO_NOTIFICATION_DISTANCES.\n                       This parameter is ignored when @ref NRF_RADIO_NOTIFICATION_TYPE_NONE or\n                       @ref NRF_RADIO_NOTIFICATION_TYPE_INT_ON_INACTIVE is used.\n\n @retval ::NRF_ERROR_INVALID_PARAM The group number is invalid.\n @retval ::NRF_ERROR_INVALID_STATE A protocol stack or other SoftDevice is running. Stop all\n                                   running activities and retry.\n @retval ::NRF_SUCCESS"]
#[inline(always)]
pub unsafe fn sd_radio_notification_cfg_set(type_: u8, distance: u8) -> u32 {
    let ret: u32;
    core::arch::asm!("svc 66",
        inout("r0") to_asm(type_) => ret,
        inout("r1") to_asm(distance) => _,
        lateout("r2") _,
        lateout("r3") _,
        lateout("r12") _,
    );
    ret
}

#[doc = "@brief Encrypts a block according to the specified parameters.\n\n 128-bit AES encryption.\n\n @note:\n    - The application may set the SEVONPEND bit in the SCR to 1 to make the SoftDevice sleep while\n      the ECB is running. The SEVONPEND bit should only be cleared (set to 0) from application\n      main or low interrupt level.\n\n @param[in, out] p_ecb_data Pointer to the ECB parameters' struct (two input\n                            parameters and one output parameter).\n\n @retval ::NRF_SUCCESS"]
#[inline(always)]
pub unsafe fn sd_ecb_block_encrypt(p_ecb_data: *mut nrf_ecb_hal_data_t) -> u32 {
    let ret: u32;
    core::arch::asm!("svc 67",
        inout("r0") to_asm(p_ecb_data) => ret,
        lateout("r1") _,
        lateout("r2") _,
        lateout("r3") _,
        lateout("r12") _,
    );
    ret
}

#[doc = "@brief Encrypts multiple data blocks provided as an array of data block structures.\n\n @details: Performs 128-bit AES encryption on multiple data blocks\n\n @note:\n    - The application may set the SEVONPEND bit in the SCR to 1 to make the SoftDevice sleep while\n      the ECB is running. The SEVONPEND bit should only be cleared (set to 0) from application\n      main or low interrupt level.\n\n @param[in]     block_count     Count of blocks in the p_data_blocks array.\n @param[in,out] p_data_blocks   Pointer to the first entry in a contiguous array of\n                                @ref nrf_ecb_hal_data_block_t structures.\n\n @retval ::NRF_SUCCESS"]
#[inline(always)]
pub unsafe fn sd_ecb_blocks_encrypt(block_count: u8, p_data_blocks: *mut nrf_ecb_hal_data_block_t) -> u32 {
    let ret: u32;
    core::arch::asm!("svc 68",
        inout("r0") to_asm(block_count) => ret,
        inout("r1") to_asm(p_data_blocks) => _,
        lateout("r2") _,
        lateout("r3") _,
        lateout("r12") _,
    );
    ret
}

#[doc = "@brief Gets any pending events generated by the SoC API.\n\n The application should keep calling this function to get events, until ::NRF_ERROR_NOT_FOUND is returned.\n\n @param[out] p_evt_id Set to one of the values in @ref NRF_SOC_EVTS, if any events are pending.\n\n @retval ::NRF_SUCCESS An event was pending. The event id is written in the p_evt_id parameter.\n @retval ::NRF_ERROR_NOT_FOUND No pending events."]
#[inline(always)]
pub unsafe fn sd_evt_get(p_evt_id: *mut u32) -> u32 {
    let ret: u32;
    core::arch::asm!("svc 72",
        inout("r0") to_asm(p_evt_id) => ret,
        lateout("r1") _,
        lateout("r2") _,
        lateout("r3") _,
        lateout("r12") _,
    );
    ret
}

#[doc = "@brief Get the temperature measured on the chip\n\n This function will block until the temperature measurement is done.\n It takes around 50 us from call to return.\n\n @param[out] p_temp Result of temperature measurement. Die temperature in 0.25 degrees Celsius.\n\n @retval ::NRF_SUCCESS A temperature measurement was done, and the temperature was written to temp"]
#[inline(always)]
pub unsafe fn sd_temp_get(p_temp: *mut i32) -> u32 {
    let ret: u32;
    core::arch::asm!("svc 73",
        inout("r0") to_asm(p_temp) => ret,
        lateout("r1") _,
        lateout("r2") _,
        lateout("r3") _,
        lateout("r12") _,
    );
    ret
}

#[doc = "@brief Flash Write\n\n Commands to write a buffer to flash\n\n If the SoftDevice is enabled:\n  This call initiates the flash access command, and its completion will be communicated to the\n  application with exactly one of the following events:\n      - @ref NRF_EVT_FLASH_OPERATION_SUCCESS - The command was successfully completed.\n      - @ref NRF_EVT_FLASH_OPERATION_ERROR   - The command could not be started.\n\n If the SoftDevice is not enabled no event will be generated, and this call will return @ref NRF_SUCCESS when the\n write has been completed\n\n @note\n      - This call takes control over the radio and the CPU during flash erase and write to make sure that\n        they will not interfere with the flash access. This means that all interrupts will be blocked\n        for a predictable time (depending on the NVMC specification in nRF51 Series Reference Manual\n        and the command parameters).\n      - The data in the p_src buffer should not be modified before the @ref NRF_EVT_FLASH_OPERATION_SUCCESS\n        or the @ref NRF_EVT_FLASH_OPERATION_ERROR have been received if the SoftDevice is enabled.\n\n\n @param[in]  p_dst Pointer to start of flash location to be written.\n @param[in]  p_src Pointer to buffer with data to be written.\n @param[in]  size  Number of 32-bit words to write. Maximum size is 256 32-bit words for nRF51 and 1024 for nRF52.\n\n @retval ::NRF_ERROR_INVALID_ADDR   Tried to write to a non existing flash address, or p_dst or p_src was unaligned.\n @retval ::NRF_ERROR_BUSY           The previous command has not yet completed.\n @retval ::NRF_ERROR_INVALID_LENGTH Size was 0, or higher than the maximum allowed size.\n @retval ::NRF_ERROR_FORBIDDEN      Tried to write to or read from protected location.\n @retval ::NRF_SUCCESS              The command was accepted."]
#[inline(always)]
pub unsafe fn sd_flash_write(p_dst: *mut u32, p_src: *const u32, size: u32) -> u32 {
    let ret: u32;
    core::arch::asm!("svc 41",
        inout("r0") to_asm(p_dst) => ret,
        inout("r1") to_asm(p_src) => _,
        inout("r2") to_asm(size) => _,
        lateout("r3") _,
        lateout("r12") _,
    );
    ret
}

#[doc = "@brief Flash Erase page\n\n Commands to erase a flash page\n If the SoftDevice is enabled:\n  This call initiates the flash access command, and its completion will be communicated to the\n  application with exactly one of the following events:\n      - @ref NRF_EVT_FLASH_OPERATION_SUCCESS - The command was successfully completed.\n      - @ref NRF_EVT_FLASH_OPERATION_ERROR   - The command could not be started.\n\n If the SoftDevice is not enabled no event will be generated, and this call will return @ref NRF_SUCCESS when the\n erase has been completed\n\n @note\n      - This call takes control over the radio and the CPU during flash erase and write to make sure that\n        they will not interfere with the flash access. This means that all interrupts will be blocked\n        for a predictable time (depending on the NVMC specification in nRF51 Series Reference Manual\n        and the command parameters).\n\n\n @param[in]  page_number           Page number of the page to erase\n\n @retval ::NRF_ERROR_INTERNAL      If a new session could not be opened due to an internal error.\n @retval ::NRF_ERROR_INVALID_ADDR  Tried to erase to a non existing flash page.\n @retval ::NRF_ERROR_BUSY          The previous command has not yet completed.\n @retval ::NRF_ERROR_FORBIDDEN     Tried to erase a protected page.\n @retval ::NRF_SUCCESS             The command was accepted."]
#[inline(always)]
pub unsafe fn sd_flash_page_erase(page_number: u32) -> u32 {
    let ret: u32;
    core::arch::asm!("svc 40",
        inout("r0") to_asm(page_number) => ret,
        lateout("r1") _,
        lateout("r2") _,
        lateout("r3") _,
        lateout("r12") _,
    );
    ret
}

#[doc = "@brief Flash Protection set\n\n Commands to set the flash protection configuration registers.\nOn nRF51 this sets the PROTENSETx registers of the MPU peripheral.\nOn nRF52 this sets the CONFIGx registers of the BPROT peripheral.\n\n @note To read the values read them directly. They are only write-protected.\n\n @param[in]  block_cfg0 Value to be written to the configuration register.\n @param[in]  block_cfg1 Value to be written to the configuration register.\n @param[in]  block_cfg2 Value to be written to the configuration register (ignored on nRF51).\n @param[in]  block_cfg3 Value to be written to the configuration register (ignored on nRF51).\n\n @retval ::NRF_ERROR_FORBIDDEN Tried to protect the SoftDevice.\n @retval ::NRF_SUCCESS Values successfully written to configuration registers."]
#[inline(always)]
pub unsafe fn sd_flash_protect(block_cfg0: u32, block_cfg1: u32, block_cfg2: u32, block_cfg3: u32) -> u32 {
    let ret: u32;
    core::arch::asm!("svc 42",
        inout("r0") to_asm(block_cfg0) => ret,
        inout("r1") to_asm(block_cfg1) => _,
        inout("r2") to_asm(block_cfg2) => _,
        inout("r3") to_asm(block_cfg3) => _,
        lateout("r12") _,
    );
    ret
}

#[doc = "@brief Opens a session for radio timeslot requests.\n\n @note Only one session can be open at a time.\n @note p_radio_signal_callback(@ref NRF_RADIO_CALLBACK_SIGNAL_TYPE_START) will be called when the radio timeslot\n       starts. From this point the NRF_RADIO and NRF_TIMER0 peripherals can be freely accessed\n       by the application.\n @note p_radio_signal_callback(@ref NRF_RADIO_CALLBACK_SIGNAL_TYPE_TIMER0) is called whenever the NRF_TIMER0\n       interrupt occurs.\n @note p_radio_signal_callback(@ref NRF_RADIO_CALLBACK_SIGNAL_TYPE_RADIO) is called whenever the NRF_RADIO\n       interrupt occurs.\n @note p_radio_signal_callback() will be called at ARM interrupt priority level 0. This\n       implies that none of the sd_* API calls can be used from p_radio_signal_callback().\n\n @param[in] p_radio_signal_callback The signal callback.\n\n @retval ::NRF_ERROR_INVALID_ADDR p_radio_signal_callback is an invalid function pointer.\n @retval ::NRF_ERROR_BUSY If session cannot be opened.\n @retval ::NRF_ERROR_INTERNAL If a new session could not be opened due to an internal error.\n @retval ::NRF_SUCCESS Otherwise."]
#[inline(always)]
pub unsafe fn sd_radio_session_open(p_radio_signal_callback: nrf_radio_signal_callback_t) -> u32 {
    let ret: u32;
    core::arch::asm!("svc 69",
        inout("r0") to_asm(p_radio_signal_callback) => ret,
        lateout("r1") _,
        lateout("r2") _,
        lateout("r3") _,
        lateout("r12") _,
    );
    ret
}

#[doc = "@brief Closes a session for radio timeslot requests.\n\n @note Any current radio timeslot will be finished before the session is closed.\n @note If a radio timeslot is scheduled when the session is closed, it will be canceled.\n @note The application cannot consider the session closed until the @ref NRF_EVT_RADIO_SESSION_CLOSED\n       event is received.\n\n @retval ::NRF_ERROR_FORBIDDEN If session not opened.\n @retval ::NRF_ERROR_BUSY If session is currently being closed.\n @retval ::NRF_SUCCESS Otherwise."]
#[inline(always)]
pub unsafe fn sd_radio_session_close() -> u32 {
    let ret: u32;
    core::arch::asm!("svc 70",
        lateout("r0") ret,
        lateout("r1") _,
        lateout("r2") _,
        lateout("r3") _,
        lateout("r12") _,
    );
    ret
}

#[doc = "@brief Requests a radio timeslot.\n\n @note The request type is determined by p_request->request_type, and can be one of @ref NRF_RADIO_REQ_TYPE_EARLIEST\n       and @ref NRF_RADIO_REQ_TYPE_NORMAL. The first request in a session must always be of type @ref NRF_RADIO_REQ_TYPE_EARLIEST.\n @note For a normal request (@ref NRF_RADIO_REQ_TYPE_NORMAL), the start time of a radio timeslot is specified by\n       p_request->distance_us and is given relative to the start of the previous timeslot.\n @note A too small p_request->distance_us will lead to a @ref NRF_EVT_RADIO_BLOCKED event.\n @note Timeslots scheduled too close will lead to a @ref NRF_EVT_RADIO_BLOCKED event.\n @note See the SoftDevice Specification for more on radio timeslot scheduling, distances and lengths.\n @note If an opportunity for the first radio timeslot is not found before 100 ms after the call to this\n       function, it is not scheduled, and instead a @ref NRF_EVT_RADIO_BLOCKED event is sent.\n       The application may then try to schedule the first radio timeslot again.\n @note Successful requests will result in nrf_radio_signal_callback_t(@ref NRF_RADIO_CALLBACK_SIGNAL_TYPE_START).\n       Unsuccessful requests will result in a @ref NRF_EVT_RADIO_BLOCKED event, see @ref NRF_SOC_EVTS.\n @note The jitter in the start time of the radio timeslots is +/- @ref NRF_RADIO_START_JITTER_US us.\n @note The nrf_radio_signal_callback_t(@ref NRF_RADIO_CALLBACK_SIGNAL_TYPE_START) call has a latency relative to the\n       specified radio timeslot start, but this does not affect the actual start time of the timeslot.\n @note NRF_TIMER0 is reset at the start of the radio timeslot, and is clocked at 1MHz from the high frequency\n       (16 MHz) clock source. If p_request->hfclk_force_xtal is true, the high frequency clock is\n       guaranteed to be clocked from the external crystal.\n @note The SoftDevice will neither access the NRF_RADIO peripheral nor the NRF_TIMER0 peripheral\n       during the radio timeslot.\n\n @param[in] p_request Pointer to the request parameters.\n\n @retval ::NRF_ERROR_FORBIDDEN If session not opened or the session is not IDLE.\n @retval ::NRF_ERROR_INVALID_ADDR If the p_request pointer is invalid.\n @retval ::NRF_ERROR_INVALID_PARAM If the parameters of p_request are not valid.\n @retval ::NRF_SUCCESS Otherwise."]
#[inline(always)]
pub unsafe fn sd_radio_request(p_request: *const nrf_radio_request_t) -> u32 {
    let ret: u32;
    core::arch::asm!("svc 71",
        inout("r0") to_asm(p_request) => ret,
        lateout("r1") _,
        lateout("r2") _,
        lateout("r3") _,
        lateout("r12") _,
    );
    ret
}

#[doc = "< ::sd_softdevice_enable"]
pub const NRF_SD_SVCS_SD_SOFTDEVICE_ENABLE: NRF_SD_SVCS = 16;
#[doc = "< ::sd_softdevice_disable"]
pub const NRF_SD_SVCS_SD_SOFTDEVICE_DISABLE: NRF_SD_SVCS = 17;
#[doc = "< ::sd_softdevice_is_enabled"]
pub const NRF_SD_SVCS_SD_SOFTDEVICE_IS_ENABLED: NRF_SD_SVCS = 18;
#[doc = "< ::sd_softdevice_vector_table_base_set"]
pub const NRF_SD_SVCS_SD_SOFTDEVICE_VECTOR_TABLE_BASE_SET: NRF_SD_SVCS = 19;
#[doc = "< Placeholder for last SDM SVC"]
pub const NRF_SD_SVCS_SVC_SDM_LAST: NRF_SD_SVCS = 20;
#[doc = "@brief nRF SoftDevice Manager API SVC numbers."]
pub type NRF_SD_SVCS = self::c_uint;
#[doc = "@brief Type representing LFCLK oscillator source."]
#[repr(C)]
#[derive(Debug, Copy, Clone)]
pub struct nrf_clock_lf_cfg_t {
    #[doc = "< LF oscillator clock source, see @ref NRF_CLOCK_LF_SRC."]
    pub source: u8,
    #[doc = "< Only for NRF_CLOCK_LF_SRC_RC: Calibration timer interval in 1/4 second\nunits (nRF51: 1-64, nRF52: 1-32).\n@note To avoid excessive clock drift, 0.5 degrees Celsius is the\nmaximum temperature change allowed in one calibration timer\ninterval. The interval should be selected to ensure this.\n\n@note Must be 0 if source is not NRF_CLOCK_LF_SRC_RC."]
    pub rc_ctiv: u8,
    #[doc = "<  Only for NRF_CLOCK_LF_SRC_RC: How often (in number of calibration\nintervals) the RC oscillator shall be calibrated if the temperature\nhasn't changed.\n0: Always calibrate even if the temperature hasn't changed.\n1: Only calibrate if the temperature has changed (nRF51 only).\n2-33: Check the temperature and only calibrate if it has changed,\nhowever calibration will take place every rc_temp_ctiv\nintervals in any case.\n\n@note Must be 0 if source is not NRF_CLOCK_LF_SRC_RC.\n\n@note For nRF52, the application must ensure calibration at least once\nevery 8 seconds to ensure +/-250 ppm clock stability. The\nrecommended configuration for NRF_CLOCK_LF_SRC_RC on nRF52 is\nrc_ctiv=16 and rc_temp_ctiv=2. This will ensure calibration at\nleast once every 8 seconds and for temperature changes of 0.5\ndegrees Celsius every 4 seconds. See the Product Specification\nfor the nRF52 device being used for more information."]
    pub rc_temp_ctiv: u8,
    #[doc = "< External crystal clock accuracy used in the LL to compute timing\nwindows, see @ref NRF_CLOCK_LF_XTAL_ACCURACY.\n\n@note For the NRF_CLOCK_LF_SRC_RC clock source this parameter is ignored."]
    pub xtal_accuracy: u8,
}
#[test]
fn bindgen_test_layout_nrf_clock_lf_cfg_t() {
    const UNINIT: ::core::mem::MaybeUninit<nrf_clock_lf_cfg_t> = ::core::mem::MaybeUninit::uninit();
    let ptr = UNINIT.as_ptr();
    assert_eq!(
        ::core::mem::size_of::<nrf_clock_lf_cfg_t>(),
        4usize,
        concat!("Size of: ", stringify!(nrf_clock_lf_cfg_t))
    );
    assert_eq!(
        ::core::mem::align_of::<nrf_clock_lf_cfg_t>(),
        1usize,
        concat!("Alignment of ", stringify!(nrf_clock_lf_cfg_t))
    );
    assert_eq!(
        unsafe { ::core::ptr::addr_of!((*ptr).source) as usize - ptr as usize },
        0usize,
        concat!(
            "Offset of field: ",
            stringify!(nrf_clock_lf_cfg_t),
            "::",
            stringify!(source)
        )
    );
    assert_eq!(
        unsafe { ::core::ptr::addr_of!((*ptr).rc_ctiv) as usize - ptr as usize },
        1usize,
        concat!(
            "Offset of field: ",
            stringify!(nrf_clock_lf_cfg_t),
            "::",
            stringify!(rc_ctiv)
        )
    );
    assert_eq!(
        unsafe { ::core::ptr::addr_of!((*ptr).rc_temp_ctiv) as usize - ptr as usize },
        2usize,
        concat!(
            "Offset of field: ",
            stringify!(nrf_clock_lf_cfg_t),
            "::",
            stringify!(rc_temp_ctiv)
        )
    );
    assert_eq!(
        unsafe { ::core::ptr::addr_of!((*ptr).xtal_accuracy) as usize - ptr as usize },
        3usize,
        concat!(
            "Offset of field: ",
            stringify!(nrf_clock_lf_cfg_t),
            "::",
            stringify!(xtal_accuracy)
        )
    );
}
#[doc = "@brief Fault Handler type.\n\n When certain unrecoverable errors occur within the application or SoftDevice the fault handler will be called back.\n The protocol stack will be in an undefined state when this happens and the only way to recover will be to\n perform a reset, using e.g. CMSIS NVIC_SystemReset().\n If the application returns from the fault handler the SoftDevice will call NVIC_SystemReset().\n\n @note This callback is executed in HardFault context, thus SVC functions cannot be called from the fault callback.\n\n @param[in] id Fault identifier. See @ref NRF_FAULT_IDS.\n @param[in] pc The program counter of the instruction that triggered the fault.\n @param[in] info Optional additional information regarding the fault. Refer to each Fault identifier for details.\n\n @note When id is set to NRF_FAULT_ID_APP_MEMACC, pc will contain the address of the instruction being executed at the time when\n the fault is detected by the CPU. The CPU program counter may have advanced up to 2 instructions (no branching) after the one that triggered the fault."]
pub type nrf_fault_handler_t = ::core::option::Option<unsafe extern "C" fn(id: u32, pc: u32, info: u32)>;

#[doc = "@brief Enables the SoftDevice and by extension the protocol stack.\n\n @note Some care must be taken if a low frequency clock source is already running when calling this function:\n       If the LF clock has a different source then the one currently running, it will be stopped. Then, the new\n       clock source will be started.\n\n @note This function has no effect when returning with an error.\n\n @post If return code is ::NRF_SUCCESS\n       - SoC library and protocol stack APIs are made available.\n       - A portion of RAM will be unavailable (see relevant SDS documentation).\n       - Some peripherals will be unavailable or available only through the SoC API (see relevant SDS documentation).\n       - Interrupts will not arrive from protected peripherals or interrupts.\n       - nrf_nvic_ functions must be used instead of CMSIS NVIC_ functions for reliable usage of the SoftDevice.\n       - Interrupt latency may be affected by the SoftDevice  (see relevant SDS documentation).\n       - Chosen low frequency clock source will be running.\n\n @param p_clock_lf_cfg Low frequency clock source and accuracy.\nIf NULL the clock will be configured as an RC source with rc_ctiv = 16 and .rc_temp_ctiv = 2\nIn the case of XTAL source, the PPM accuracy of the chosen clock source must be greater than or equal to the actual characteristics of your XTAL clock.\n @param fault_handler Callback to be invoked in case of fault, cannot be NULL.\n\n @retval ::NRF_SUCCESS\n @retval ::NRF_ERROR_INVALID_ADDR  Invalid or NULL pointer supplied.\n @retval ::NRF_ERROR_INVALID_STATE SoftDevice is already enabled, and the clock source and fault handler cannot be updated.\n @retval ::NRF_ERROR_SDM_INCORRECT_INTERRUPT_CONFIGURATION SoftDevice interrupt is already enabled, or an enabled interrupt has an illegal priority level.\n @retval ::NRF_ERROR_SDM_LFCLK_SOURCE_UNKNOWN Unknown low frequency clock source selected."]
#[inline(always)]
pub unsafe fn sd_softdevice_enable(
    p_clock_lf_cfg: *const nrf_clock_lf_cfg_t,
    fault_handler: nrf_fault_handler_t,
) -> u32 {
    let ret: u32;
    core::arch::asm!("svc 16",
        inout("r0") to_asm(p_clock_lf_cfg) => ret,
        inout("r1") to_asm(fault_handler) => _,
        lateout("r2") _,
        lateout("r3") _,
        lateout("r12") _,
    );
    ret
}

#[doc = "@brief Disables the SoftDevice and by extension the protocol stack.\n\n Idempotent function to disable the SoftDevice.\n\n @post SoC library and protocol stack APIs are made unavailable.\n @post All interrupts that was protected by the SoftDevice will be disabled and initialized to priority 0 (highest).\n @post All peripherals used by the SoftDevice will be reset to default values.\n @post All of RAM become available.\n @post All interrupts are forwarded to the application.\n @post LFCLK source chosen in ::sd_softdevice_enable will be left running.\n\n @retval ::NRF_SUCCESS"]
#[inline(always)]
pub unsafe fn sd_softdevice_disable() -> u32 {
    let ret: u32;
    core::arch::asm!("svc 17",
        lateout("r0") ret,
        lateout("r1") _,
        lateout("r2") _,
        lateout("r3") _,
        lateout("r12") _,
    );
    ret
}

#[doc = "@brief Check if the SoftDevice is enabled.\n\n @param[out]  p_softdevice_enabled If the SoftDevice is enabled: 1 else 0.\n\n @retval ::NRF_SUCCESS"]
#[inline(always)]
pub unsafe fn sd_softdevice_is_enabled(p_softdevice_enabled: *mut u8) -> u32 {
    let ret: u32;
    core::arch::asm!("svc 18",
        inout("r0") to_asm(p_softdevice_enabled) => ret,
        lateout("r1") _,
        lateout("r2") _,
        lateout("r3") _,
        lateout("r12") _,
    );
    ret
}

#[doc = "@brief Sets the base address of the interrupt vector table for interrupts forwarded from the SoftDevice\n\n This function is only intended to be called when a bootloader is enabled.\n\n @param[in] address The base address of the interrupt vector table for forwarded interrupts.\n\n @retval ::NRF_SUCCESS"]
#[inline(always)]
pub unsafe fn sd_softdevice_vector_table_base_set(address: u32) -> u32 {
    let ret: u32;
    core::arch::asm!("svc 19",
        inout("r0") to_asm(address) => ret,
        lateout("r1") _,
        lateout("r2") _,
        lateout("r3") _,
        lateout("r12") _,
    );
    ret
}

